def _count_atoms_of_symbol(atom_spec: str, symbol: str) -> int:
    normalized = symbol.strip().lower()
    count = 0
    for line in atom_spec.splitlines():
        parts = line.split()
        if parts and parts[0].lower() == normalized:
            count += 1
    return count


def _acene_chain_index(atom_spec: str) -> int:
    """Recover the acene repeat-unit index from its carbon stoichiometry.

    An acene with n fused rings has the formula C_{4n+2}H_{2n+4}, so the
    carbon count alone fixes n without relying on the label spelling.
    """
    carbon_count = _count_atoms_of_symbol(atom_spec, "C")
    chain_index = (carbon_count - 2) // 4
    if chain_index < 1 or (carbon_count - 2) % 4 != 0:
        raise ValueError(
            f"Cannot interpret carbon count {carbon_count} as an acene chain index"
        )
    return chain_index

